/* @socom-skeleton body Create__Q23zdb3CDIFRQ23zdb9CSaveLoad */
namespace zdb {
CDI* CDI::Create(CSaveLoad& sload)
    {
        CDI* di = NULL;
        zar::CKey* dikey = sload.m_zfile.GetOpenKey();

        if (dikey)
        {
            di = new CDIPoly();

            // Failed to read?
            if (!di->Read(sload))
            {
                delete di;
                di = NULL;
            }
        }

        return di;
    }
}

/* @socom-skeleton body Read__Q23zdb3CDIFRQ23zdb9CSaveLoad */
namespace zdb {
bool CDI::Read(CSaveLoad& sload)
    {
        /* 0x21c340. The params go into the DI_PARAMS base, not over GCC's vptr at `this`. */
        if (!sload.m_zfile.GetOpenKey())
            return false;

        if (!sload.m_zfile.Fetch("params", static_cast<DI_PARAMS*>(this), sizeof(DI_PARAMS)))
            return false;

        if (m_ditype == 0)
            m_ditype = 3;

        Allocate((int)m_ptcount);

        bool result = sload.m_zfile.Fetch("points", m_pts, m_ptcount * sizeof(CPnt4D));
        m_refcount = 0;

        return result;
    }
}

